    [19209] = {"设计图：黑色怒火", "拾取后绑定\n双手\n+15 耐力\n+31 力量\n装备：近战和远程攻击爆击几率提高 1%。\n速度 2.10\n需要 锻造 (300)\n装备后绑定\n105 - 158 伤害\n（每秒造成 62.6 点伤害）\n+10 火焰抗性\n需要等级 60\n物品等级 66", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Two-Hand"] = "双手", ["+15 Stamina"] = "+15 耐力", ["+31 Strength"] = "+31 力量", ["Equip: Improves your chance to get a critical strike with melee and ranged attacks by 1%."] = "装备：近战和远程攻击爆击几率提高 1%。", ["Speed 2.10"] = "速度 2.10", ["Requires Blacksmithing (300)"] = "需要 锻造 (300)", ["Binds when equipped"] = "装备后绑定", ["105 - 158 Damage"] = "105 - 158 伤害", ["(62.6 damage per second)"] = "（每秒造成 62.6 点伤害）", ["+10 Fire Resistance"] = "+10 火焰抗性", ["Requires Level 60"] = "需要等级 60", ["Item Level 66"] = "物品等级 66" }, "Plans: Blackfury"},
