    [20039] = {"黑铁长靴", "装备后绑定\n脚\n514 护甲\n+25 火焰抗性\n需要等级 60\n物品等级 66\n(2) 套装：+10 火焰抗性\n(4) 套装：与元素生物作战时，攻击强度提高 36 点。\n(6) 套装：近战和远程攻击命中几率提高 1%。\n(8) 套装：当你身处火焰之王影响的区域时，攻击强度和法术伤害提高 75 点。", "EpochHead 物品", "item", { ["Binds when equipped"] = "装备后绑定", ["Feet"] = "脚", ["514 Armor"] = "514 护甲", ["+25 Fire Resistance"] = "+25 火焰抗性", ["Requires Level 60"] = "需要等级 60", ["Item Level 66"] = "物品等级 66", ["(2) Set: +10 Fire Resistance."] = "(2) 套装：+10 火焰抗性", ["(4) Set: +36 Attack Power when fighting Elementals."] = "(4) 套装：与元素生物作战时，攻击强度提高 36 点。", ["(6) Set: Improves your chance to hit with melee and ranged attacks by 1%."] = "(6) 套装：近战和远程攻击命中几率提高 1%。", ["(8) Set: While you are in an area touched by the Firelord, your attack power and spell damage is increased by 75."] = "(8) 套装：当你身处火焰之王影响的区域时，攻击强度和法术伤害提高 75 点。" }, "Dark Iron Boots"},
    [20040] = {"设计图：黑铁长靴", "拾取后绑定\n脚\n514 护甲\n需要 锻造 (300)\n装备后绑定\n+25 火焰抗性\n需要等级 60\n物品等级 66\n(2) 套装：+10 火焰抗性\n(4) 套装：与元素生物作战时，攻击强度提高 36 点。\n(6) 套装：近战和远程攻击命中几率提高 1%。\n(8) 套装：当你身处火焰之王影响的区域时，攻击强度和法术伤害提高 75 点。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Feet"] = "脚", ["514 Armor"] = "514 护甲", ["Requires Blacksmithing (300)"] = "需要 锻造 (300)", ["Binds when equipped"] = "装备后绑定", ["+25 Fire Resistance"] = "+25 火焰抗性", ["Requires Level 60"] = "需要等级 60", ["Item Level 66"] = "物品等级 66", ["(2) Set: +10 Fire Resistance."] = "(2) 套装：+10 火焰抗性", ["(4) Set: +36 Attack Power when fighting Elementals."] = "(4) 套装：与元素生物作战时，攻击强度提高 36 点。", ["(6) Set: Improves your chance to hit with melee and ranged attacks by 1%."] = "(6) 套装：近战和远程攻击命中几率提高 1%。", ["(8) Set: While you are in an area touched by the Firelord, your attack power and spell damage is increased by 75."] = "(8) 套装：当你身处火焰之王影响的区域时，攻击强度和法术伤害提高 75 点。" }, "Plans: Dark Iron Boots"},
    [20065] = {"阿拉希盆地魔纹布绷带", "拾取后绑定\n使用：在 8秒 内治疗 1104 点伤害。只能在阿拉希盆地中使用。\n需要等级 35\n需要 急救 (175)", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Use: Heals 1104 damage over 8 sec. Usable only inside Arathi Basin."] = "使用：在 8秒 内治疗 1104 点伤害。只能在阿拉希盆地中使用。", ["Requires Level 35"] = "需要等级 35", ["Requires First Aid (175)"] = "需要 急救 (175)" }, "Arathi Basin Mageweave Bandage"},
    [20074] = {"鳄鱼炖肉", "使用：在 27秒 内恢复 874 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，8 耐力和精神，持续 15分钟。\n需要等级 20", "EpochHead 物品", "item", { ["Use: Restores 874 health over 27 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 8 Stamina and Spirit for 15 min."] = "使用：在 27秒 内恢复 874 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，8 耐力和精神，持续 15分钟。", ["Requires Level 20"] = "需要等级 20" }, "Heavy Crocolisk Stew"},
