    [60851] = {"新手兜帽", "拾取后绑定\n头部\n45 护甲\n+3 智力\n+4 耐力\n装备：受到其他玩家的伤害降低 2%。\n职业：牧师、法师、术士\n需要等级 15\n物品等级 20\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 7 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 31 点生命值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Head"] = "头部", ["45 Armor"] = "45 护甲", ["+3 Intellect"] = "+3 智力", ["+4 Stamina"] = "+4 耐力", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Priest, Mage, Warlock"] = "职业：牧师、法师、术士", ["Requires Level 15"] = "需要等级 15", ["Item Level 20"] = "物品等级 20", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases damage and healing done by magical spells and effects by up to 7."] = "(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 7 点。", ["(6) Set: Restores 31 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 31 点生命值。该效果每 10 秒只能触发一次。" }, "Rookie's Hood"},
    [60852] = {"新秀披风", "拾取后绑定\n肩部\n43 护甲\n+3 精神\n+4 耐力\n装备：受到其他玩家的伤害降低 2%。\n职业：牧师、法师、术士\n需要等级 15\n物品等级 20\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 7 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 31 点生命值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Shoulder"] = "肩部", ["43 Armor"] = "43 护甲", ["+3 Spirit"] = "+3 精神", ["+4 Stamina"] = "+4 耐力", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Priest, Mage, Warlock"] = "职业：牧师、法师、术士", ["Requires Level 15"] = "需要等级 15", ["Item Level 20"] = "物品等级 20", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases damage and healing done by magical spells and effects by up to 7."] = "(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 7 点。", ["(6) Set: Restores 31 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 31 点生命值。该效果每 10 秒只能触发一次。" }, "Rookie's Mantle"},
