    [61063] = {"战斗者的服装", "拾取后绑定\n胸部\n81 护甲\n+15 耐力\n装备：所有魔法法术和效果的治疗效果最多提高 22 点，造成的伤害最多提高 7 点。\n装备：受到其他玩家的伤害降低 2%。\n职业：牧师、法师、术士\n需要等级 35\n物品等级 40\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：所有魔法法术和效果的治疗效果最多提高 37 点，造成的伤害最多提高 13 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 173 点法力值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Chest"] = "胸部", ["81 Armor"] = "81 护甲", ["+15 Stamina"] = "+15 耐力", ["Equip: Increases healing done by up to 22 and damage done by up to 7 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 22 点，造成的伤害最多提高 7 点。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Priest, Mage, Warlock"] = "职业：牧师、法师、术士", ["Requires Level 35"] = "需要等级 35", ["Item Level 40"] = "物品等级 40", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases healing done by up to 37 and damage done by up to 13 for all magical spells and effects."] = "(4) 套装：所有魔法法术和效果的治疗效果最多提高 37 点，造成的伤害最多提高 13 点。", ["(6) Set: Restores 173 mana when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 173 点法力值。该效果每 10 秒只能触发一次。" }, "Combatant's Raiment"},
