    [61099] = {"战斗者的手腕", "拾取后绑定\n手腕\n101 护甲\n+8 耐力\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 6 点。\n装备：受到其他玩家的伤害降低 1%。\n职业：战士、圣骑士\n需要等级 35\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 19 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 87 点生命值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Wrist"] = "手腕", ["101 Armor"] = "101 护甲", ["+8 Stamina"] = "+8 耐力", ["Equip: Increases damage and healing done by magical spells and effects by up to 6."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 6 点。", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["Classes: Warrior, Paladin"] = "职业：战士、圣骑士", ["Requires Level 35"] = "需要等级 35", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases damage and healing done by magical spells and effects by up to 19."] = "(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 19 点。", ["(6) Set: Restores 87 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 87 点生命值。该效果每 10 秒只能触发一次。" }, "Combatant's Wrists"},
    [61100] = {"战斗者的带扣", "拾取后绑定\n腰部\n130 护甲\n+7 智力\n+11 耐力\n装备：受到其他玩家的伤害降低 1%。\n职业：战士、圣骑士\n需要等级 35\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 19 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 87 点生命值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Waist"] = "腰部", ["130 Armor"] = "130 护甲", ["+7 Intellect"] = "+7 智力", ["+11 Stamina"] = "+11 耐力", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["Classes: Warrior, Paladin"] = "职业：战士、圣骑士", ["Requires Level 35"] = "需要等级 35", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases damage and healing done by magical spells and effects by up to 19."] = "(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 19 点。", ["(6) Set: Restores 87 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 87 点生命值。该效果每 10 秒只能触发一次。" }, "Combatant's Buckle"},
