    [61137] = {"部落战斗者徽章", "拾取后绑定\n饰品\n使用：移除所有限制移动的效果，以及所有使你失去角色控制的效果。（2分钟冷却）\n唯一装备\n种族：兽人、亡灵、牛头人、巨魔\n需要等级 35\n物品等级 40\n(2) 套装：在竞技场、战场和玩家对战目标区域中，主属性提高 6 点，额外获得 21 点耐力。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Trinket"] = "饰品", ["Use: Removes all movement impairing effects and all effects which cause loss of control of your character. (2 Min Cooldown)"] = "使用：移除所有限制移动的效果，以及所有使你失去角色控制的效果。（2分钟冷却）", ["Unique-Equipped"] = "唯一装备", ["Races: Orc, Undead, Tauren, Troll"] = "种族：兽人、亡灵、牛头人、巨魔", ["Requires Level 35"] = "需要等级 35", ["Item Level 40"] = "物品等级 40", ["(2) Set: Increases your Primary Stats by 6 and Stamina by an additional 21 when in Arenas, Battlegrounds, and PvP Objectives."] = "(2) 套装：在竞技场、战场和玩家对战目标区域中，主属性提高 6 点，额外获得 21 点耐力。" }, "Combatant's Insignia of the Horde"},
    [61138] = {"联盟战斗者徽章", "拾取后绑定\n饰品\n使用：移除所有限制移动的效果，以及所有使你失去角色控制的效果。（2分钟冷却）\n唯一装备\n种族：人类、矮人、暗夜精灵、侏儒\n需要等级 35\n物品等级 40\n(2) 套装：在竞技场、战场和玩家对战目标区域中，主属性提高 6 点，额外获得 21 点耐力。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Trinket"] = "饰品", ["Use: Removes all movement impairing effects and all effects which cause loss of control of your character. (2 Min Cooldown)"] = "使用：移除所有限制移动的效果，以及所有使你失去角色控制的效果。（2分钟冷却）", ["Unique-Equipped"] = "唯一装备", ["Races: Human, Dwarf, Night Elf, Gnome"] = "种族：人类、矮人、暗夜精灵、侏儒", ["Requires Level 35"] = "需要等级 35", ["Item Level 40"] = "物品等级 40", ["(2) Set: Increases your Primary Stats by 6 and Stamina by an additional 21 when in Arenas, Battlegrounds, and PvP Objectives."] = "(2) 套装：在竞技场、战场和玩家对战目标区域中，主属性提高 6 点，额外获得 21 点耐力。" }, "Combatant's Insignia of the Alliance"},
