    [61189] = {"候选者的腰带", "拾取后绑定\n腰部\n44 护甲\n+14 耐力\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 11 点。\n装备：受到其他玩家的伤害降低 1%。\n职业：牧师、法师、术士\n需要等级 45\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Waist"] = "腰部", ["44 Armor"] = "44 护甲", ["+14 Stamina"] = "+14 耐力", ["Equip: Increases damage and healing done by magical spells and effects by up to 11."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 11 点。", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["Classes: Priest, Mage, Warlock"] = "职业：牧师、法师、术士", ["Requires Level 45"] = "需要等级 45", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases damage and healing done by magical spells and effects by up to 24."] = "(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。", ["(6) Set: Restores 129 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。" }, "Aspirant's Waistband"},
    [61190] = {"候选者的兜帽", "拾取后绑定\n头部\n58 护甲\n+10 智力\n+15 耐力\n装备：受到其他玩家的伤害降低 2%。\n职业：牧师、法师、术士\n需要等级 45\n物品等级 50\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：所有魔法法术和效果的治疗效果最多提高 48 点，造成的伤害最多提高 16 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 257 点法力值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Head"] = "头部", ["58 Armor"] = "58 护甲", ["+10 Intellect"] = "+10 智力", ["+15 Stamina"] = "+15 耐力", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Priest, Mage, Warlock"] = "职业：牧师、法师、术士", ["Requires Level 45"] = "需要等级 45", ["Item Level 50"] = "物品等级 50", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases healing done by up to 48 and damage done by up to 16 for all magical spells and effects."] = "(4) 套装：所有魔法法术和效果的治疗效果最多提高 48 点，造成的伤害最多提高 16 点。", ["(6) Set: Restores 257 mana when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 257 点法力值。该效果每 10 秒只能触发一次。" }, "Aspirant's Cowl"},
