    [61233] = {"候选者的半干甲", "拾取后绑定\n手\n170 护甲\n+10 智力\n+15 耐力\n装备：受到其他玩家的伤害降低 1%。\n职业：战士、圣骑士、猎人、萨满祭司\n需要等级 45\n物品等级 50\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Hands"] = "手", ["170 Armor"] = "170 护甲", ["+10 Intellect"] = "+10 智力", ["+15 Stamina"] = "+15 耐力", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["Classes: Warrior, Paladin, Hunter, Shaman"] = "职业：战士、圣骑士、猎人、萨满祭司", ["Requires Level 45"] = "需要等级 45", ["Item Level 50"] = "物品等级 50", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases damage and healing done by magical spells and effects by up to 24."] = "(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。", ["(6) Set: Restores 129 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。" }, "Aspirant's Demi-gaunts"},
    [61234] = {"候选者的腿环", "拾取后绑定\n腿部\n239 护甲\n+19 耐力\n装备：法术命中几率提高 1%。\n装备：受到其他玩家的伤害降低 2%。\n职业：战士、圣骑士、猎人、萨满祭司\n需要等级 45\n物品等级 50\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Legs"] = "腿部", ["239 Armor"] = "239 护甲", ["+19 Stamina"] = "+19 耐力", ["Equip: Improves your chance to hit with spells by 1%."] = "装备：法术命中几率提高 1%。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Warrior, Paladin, Hunter, Shaman"] = "职业：战士、圣骑士、猎人、萨满祭司", ["Requires Level 45"] = "需要等级 45", ["Item Level 50"] = "物品等级 50", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases damage and healing done by magical spells and effects by up to 24."] = "(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。", ["(6) Set: Restores 129 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。" }, "Aspirant's Leglinks"},
    [61235] = {"候选者的靴链", "拾取后绑定\n脚\n188 护甲\n+8 智力\n+5 精神\n+12 耐力\n装备：受到其他玩家的伤害降低 1%。\n职业：战士、圣骑士、猎人、萨满祭司\n需要等级 45\n物品等级 50\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Feet"] = "脚", ["188 Armor"] = "188 护甲", ["+8 Intellect"] = "+8 智力", ["+5 Spirit"] = "+5 精神", ["+12 Stamina"] = "+12 耐力", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["Classes: Warrior, Paladin, Hunter, Shaman"] = "职业：战士、圣骑士、猎人、萨满祭司", ["Requires Level 45"] = "需要等级 45", ["Item Level 50"] = "物品等级 50", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases damage and healing done by magical spells and effects by up to 24."] = "(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。", ["(6) Set: Restores 129 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。" }, "Aspirant's Bootlinks"},
    [61236] = {"候选者的手腕", "拾取后绑定\n手腕\n119 护甲\n+7 智力\n+11 耐力\n装备：受到其他玩家的伤害降低 1%。\n职业：战士、圣骑士、猎人、萨满祭司\n需要等级 45\n物品等级 50\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Wrist"] = "手腕", ["119 Armor"] = "119 护甲", ["+7 Intellect"] = "+7 智力", ["+11 Stamina"] = "+11 耐力", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["Classes: Warrior, Paladin, Hunter, Shaman"] = "职业：战士、圣骑士、猎人、萨满祭司", ["Requires Level 45"] = "需要等级 45", ["Item Level 50"] = "物品等级 50", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases damage and healing done by magical spells and effects by up to 24."] = "(4) 套装：魔法法术和效果造成的伤害与治疗效果最多提高 24 点。", ["(6) Set: Restores 129 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 129 点生命值。该效果每 10 秒只能触发一次。" }, "Aspirant's Wrists"},
