    [61238] = {"候选者的锁链钟形胸衣", "拾取后绑定\n头部\n222 护甲\n+10 智力\n+15 耐力\n装备：受到其他玩家的伤害降低 2%。\n职业：战士、圣骑士、猎人、萨满祭司\n需要等级 45\n物品等级 50\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：所有魔法法术和效果的治疗效果最多提高 48 点，造成的伤害最多提高 16 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 257 点法力值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Head"] = "头部", ["222 Armor"] = "222 护甲", ["+10 Intellect"] = "+10 智力", ["+15 Stamina"] = "+15 耐力", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Warrior, Paladin, Hunter, Shaman"] = "职业：战士、圣骑士、猎人、萨满祭司", ["Requires Level 45"] = "需要等级 45", ["Item Level 50"] = "物品等级 50", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases healing done by up to 48 and damage done by up to 16 for all magical spells and effects."] = "(4) 套装：所有魔法法术和效果的治疗效果最多提高 48 点，造成的伤害最多提高 16 点。", ["(6) Set: Restores 257 mana when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 257 点法力值。该效果每 10 秒只能触发一次。" }, "Aspirant's Chain Cloche"},
    [61239] = {"候选者的轻肩甲", "拾取后绑定\n肩部\n222 护甲\n+10 精神\n+15 耐力\n装备：受到其他玩家的伤害降低 2%。\n职业：战士、圣骑士、猎人、萨满祭司\n需要等级 45\n物品等级 50\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：所有魔法法术和效果的治疗效果最多提高 48 点，造成的伤害最多提高 16 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 257 点法力值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Shoulder"] = "肩部", ["222 Armor"] = "222 护甲", ["+10 Spirit"] = "+10 精神", ["+15 Stamina"] = "+15 耐力", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Warrior, Paladin, Hunter, Shaman"] = "职业：战士、圣骑士、猎人、萨满祭司", ["Requires Level 45"] = "需要等级 45", ["Item Level 50"] = "物品等级 50", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases healing done by up to 48 and damage done by up to 16 for all magical spells and effects."] = "(4) 套装：所有魔法法术和效果的治疗效果最多提高 48 点，造成的伤害最多提高 16 点。", ["(6) Set: Restores 257 mana when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 257 点法力值。该效果每 10 秒只能触发一次。" }, "Aspirant's Light Pauldrons"},
    [61240] = {"候选者的锁甲", "拾取后绑定\n胸部\n273 护甲\n+20 耐力\n装备：所有魔法法术和效果的治疗效果最多提高 29 点，造成的伤害最多提高 9 点。\n装备：受到其他玩家的伤害降低 2%。\n职业：战士、圣骑士、猎人、萨满祭司\n需要等级 45\n物品等级 50\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：所有魔法法术和效果的治疗效果最多提高 48 点，造成的伤害最多提高 16 点。\n(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 257 点法力值。该效果每 10 秒只能触发一次。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Chest"] = "胸部", ["273 Armor"] = "273 护甲", ["+20 Stamina"] = "+20 耐力", ["Equip: Increases healing done by up to 29 and damage done by up to 9 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 29 点，造成的伤害最多提高 9 点。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Warrior, Paladin, Hunter, Shaman"] = "职业：战士、圣骑士、猎人、萨满祭司", ["Requires Level 45"] = "需要等级 45", ["Item Level 50"] = "物品等级 50", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases healing done by up to 48 and damage done by up to 16 for all magical spells and effects."] = "(4) 套装：所有魔法法术和效果的治疗效果最多提高 48 点，造成的伤害最多提高 16 点。", ["(6) Set: Restores 257 mana when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds."] = "(6) 套装：当你杀死一个提供经验或荣誉的目标时，恢复 257 点法力值。该效果每 10 秒只能触发一次。" }, "Aspirant's Hauberk"},
