    [61354] = {"战斗法师靴子", "拾取后绑定\n脚\n54 护甲\n+10 智力\n+12 耐力\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 13 点。\n装备：你的法术目标的魔法抗性降低 10 点。\n装备：受到其他玩家的伤害降低 1%。\n职业：法师\n需要等级 55\n物品等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Feet"] = "脚", ["54 Armor"] = "54 护甲", ["+10 Intellect"] = "+10 智力", ["+12 Stamina"] = "+12 耐力", ["Equip: Increases damage and healing done by magical spells and effects by up to 13."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 13 点。", ["Equip: Decreases the magical resistances of your spell targets by 10."] = "装备：你的法术目标的魔法抗性降低 10 点。", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["Classes: Mage"] = "职业：法师", ["Requires Level 55"] = "需要等级 55", ["Item Level 55"] = "物品等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。" }, "Battlemage Boots"},
    [61355] = {"神圣皇冠", "拾取后绑定\n头部\n64 护甲\n+17 智力\n+19 耐力\n装备：所有魔法法术和效果的治疗效果最多提高 21 点，造成的伤害最多提高 6 点。\n装备：受到其他玩家的伤害降低 2%。\n职业：牧师\n需要等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：真言术：盾造成的虚弱灵魂效果持续时间缩短 2 秒。\n(6) 套装：渐隐术现在还会使你获得 10% 的躲闪攻击几率。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Head"] = "头部", ["64 Armor"] = "64 护甲", ["+17 Intellect"] = "+17 智力", ["+19 Stamina"] = "+19 耐力", ["Equip: Increases healing done by up to 21 and damage done by up to 6 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 21 点，造成的伤害最多提高 6 点。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Priest"] = "职业：牧师", ["Requires Level 55"] = "需要等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Reduces the duration of the Weakened Soul effect caused by your Power Word: Shield by 2 sec."] = "(4) 套装：真言术：盾造成的虚弱灵魂效果持续时间缩短 2 秒。", ["(6) Set: Fade now also grants you a 10% chance to dodge attacks."] = "(6) 套装：渐隐术现在还会使你获得 10% 的躲闪攻击几率。" }, "Divined Crown"},
