    [61367] = {"暗影法师面具", "拾取后绑定\n头部\n64 护甲\n+12 智力\n+15 耐力\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 14 点。\n装备：法术爆击几率提高 1%。\n装备：受到其他玩家的伤害降低 2%。\n职业：术士\n需要等级 55\n物品等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：献祭的施法时间缩短 0.2 秒。\n(6) 套装：你的宠物恢复相当于你造成伤害 15% 的生命值。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Head"] = "头部", ["64 Armor"] = "64 护甲", ["+12 Intellect"] = "+12 智力", ["+15 Stamina"] = "+15 耐力", ["Equip: Increases damage and healing done by magical spells and effects by up to 14."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 14 点。", ["Equip: Improves your chance to get a critical strike with spells by 1%."] = "装备：法术爆击几率提高 1%。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Warlock"] = "职业：术士", ["Requires Level 55"] = "需要等级 55", ["Item Level 55"] = "物品等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Reduces the casting time of your Immolate spell by 0.2 sec."] = "(4) 套装：献祭的施法时间缩短 0.2 秒。", ["(6) Set: Causes your pet to be healed for 15% of the damage you deal."] = "(6) 套装：你的宠物恢复相当于你造成伤害 15% 的生命值。" }, "Shadowcaster Mask"},
    [61368] = {"暗影法师披风", "拾取后绑定\n肩部\n59 护甲\n+11 智力\n+14 耐力\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 13 点。\n装备：受到其他玩家的伤害降低 2%。\n职业：术士\n需要等级 55\n物品等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：献祭的施法时间缩短 0.2 秒。\n(6) 套装：你的宠物恢复相当于你造成伤害 15% 的生命值。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Shoulder"] = "肩部", ["59 Armor"] = "59 护甲", ["+11 Intellect"] = "+11 智力", ["+14 Stamina"] = "+14 耐力", ["Equip: Increases damage and healing done by magical spells and effects by up to 13."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 13 点。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Warlock"] = "职业：术士", ["Requires Level 55"] = "需要等级 55", ["Item Level 55"] = "物品等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Reduces the casting time of your Immolate spell by 0.2 sec."] = "(4) 套装：献祭的施法时间缩短 0.2 秒。", ["(6) Set: Causes your pet to be healed for 15% of the damage you deal."] = "(6) 套装：你的宠物恢复相当于你造成伤害 15% 的生命值。" }, "Shadowcaster Mantle"},
