    [61471] = {"正义腿甲", "拾取后绑定\n腿部\n505 护甲\n+4 智力\n+18 耐力\n+12 力量\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 13 点。\n装备：近战和远程攻击爆击几率提高 1%。\n装备：受到其他玩家的伤害降低 2%。\n职业：圣骑士\n需要等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：自由之手的冷却时间缩短 3 秒。\n(6) 套装：复仇之怒被驱散的几率降低 40% 。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Legs"] = "腿部", ["505 Armor"] = "505 护甲", ["+4 Intellect"] = "+4 智力", ["+18 Stamina"] = "+18 耐力", ["+12 Strength"] = "+12 力量", ["Equip: Increases damage and healing done by magical spells and effects by up to 13."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 13 点。", ["Equip: Improves your chance to get a critical strike with melee and ranged attacks by 1%."] = "装备：近战和远程攻击爆击几率提高 1%。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Paladin"] = "职业：圣骑士", ["Requires Level 55"] = "需要等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Hand of Freedom's cooldown is reduced by 3 seconds."] = "(4) 套装：自由之手的冷却时间缩短 3 秒。", ["(6) Set: Reduces your chance that Avenging Wrath will be dispelled by 40%."] = "(6) 套装：复仇之怒被驱散的几率降低 40% 。" }, "Righteous Legplates"},
    [61472] = {"公正长靴", "拾取后绑定\n脚\n397 护甲\n+7 智力\n+15 耐力\n+9 力量\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 9 点。\n装备：受到其他玩家的伤害降低 1%。\n装备：每5秒恢复 1 点法力值。\n职业：圣骑士\n需要等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：自由之手的冷却时间缩短 3 秒。\n(6) 套装：复仇之怒被驱散的几率降低 40% 。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Feet"] = "脚", ["397 Armor"] = "397 护甲", ["+7 Intellect"] = "+7 智力", ["+15 Stamina"] = "+15 耐力", ["+9 Strength"] = "+9 力量", ["Equip: Increases damage and healing done by magical spells and effects by up to 9."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 9 点。", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["Equip: Restores 1 mana per 5 sec."] = "装备：每5秒恢复 1 点法力值。", ["Classes: Paladin"] = "职业：圣骑士", ["Requires Level 55"] = "需要等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Hand of Freedom's cooldown is reduced by 3 seconds."] = "(4) 套装：自由之手的冷却时间缩短 3 秒。", ["(6) Set: Reduces your chance that Avenging Wrath will be dispelled by 40%."] = "(6) 套装：复仇之怒被驱散的几率降低 40% 。" }, "Righteous Boots"},
    [61473] = {"诚实头盔", "拾取后绑定\n头部\n469 护甲\n+14 智力\n+19 耐力\n装备：所有魔法法术和效果的治疗效果最多提高 16 点，造成的伤害最多提高 5 点。\n装备：法术爆击几率提高 1%。\n装备：受到其他玩家的伤害降低 2%。\n职业：圣骑士\n需要等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：神圣震击作为治疗法术使用时，受到的法术强度加成提高 10%。\n(6) 套装：你的清洁术还会为目标恢复 200. 点生命值。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Head"] = "头部", ["469 Armor"] = "469 护甲", ["+14 Intellect"] = "+14 智力", ["+19 Stamina"] = "+19 耐力", ["Equip: Increases healing done by up to 16 and damage done by up to 5 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 16 点，造成的伤害最多提高 5 点。", ["Equip: Improves your chance to get a critical strike with spells by 1%."] = "装备：法术爆击几率提高 1%。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Paladin"] = "职业：圣骑士", ["Requires Level 55"] = "需要等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases the effective spell power of your Holy Shock when used as a healing spell by 10%."] = "(4) 套装：神圣震击作为治疗法术使用时，受到的法术强度加成提高 10%。", ["(6) Set: Your Cleanse spell also heals the target for 200."] = "(6) 套装：你的清洁术还会为目标恢复 200. 点生命值。" }, "Truthful Helm"},
    [61474] = {"诚实肩甲", "拾取后绑定\n肩部\n434 护甲\n+10 智力\n+16 耐力\n装备：所有魔法法术和效果的治疗效果最多提高 10 点，造成的伤害最多提高 3 点。\n装备：法术爆击几率提高 1%。\n装备：受到其他玩家的伤害降低 2%。\n职业：圣骑士\n需要等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：神圣震击作为治疗法术使用时，受到的法术强度加成提高 10%。\n(6) 套装：你的清洁术还会为目标恢复 200. 点生命值。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Shoulder"] = "肩部", ["434 Armor"] = "434 护甲", ["+10 Intellect"] = "+10 智力", ["+16 Stamina"] = "+16 耐力", ["Equip: Increases healing done by up to 10 and damage done by up to 3 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 10 点，造成的伤害最多提高 3 点。", ["Equip: Improves your chance to get a critical strike with spells by 1%."] = "装备：法术爆击几率提高 1%。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Paladin"] = "职业：圣骑士", ["Requires Level 55"] = "需要等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases the effective spell power of your Holy Shock when used as a healing spell by 10%."] = "(4) 套装：神圣震击作为治疗法术使用时，受到的法术强度加成提高 10%。", ["(6) Set: Your Cleanse spell also heals the target for 200."] = "(6) 套装：你的清洁术还会为目标恢复 200. 点生命值。" }, "Truthful Spaulders"},
    [61475] = {"诚实胸甲", "拾取后绑定\n胸部\n577 护甲\n+7 智力\n+16 耐力\n装备：所有魔法法术和效果的治疗效果最多提高 18 点，造成的伤害最多提高 5 点。\n装备：法术爆击几率提高 1%。\n装备：受到其他玩家的伤害降低 2%。\n装备：每5秒恢复 4 点法力值。\n职业：圣骑士\n需要等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：神圣震击作为治疗法术使用时，受到的法术强度加成提高 10%。\n(6) 套装：你的清洁术还会为目标恢复 200. 点生命值。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Chest"] = "胸部", ["577 Armor"] = "577 护甲", ["+7 Intellect"] = "+7 智力", ["+16 Stamina"] = "+16 耐力", ["Equip: Increases healing done by up to 18 and damage done by up to 5 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 18 点，造成的伤害最多提高 5 点。", ["Equip: Improves your chance to get a critical strike with spells by 1%."] = "装备：法术爆击几率提高 1%。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Equip: Restores 4 mana per 5 sec."] = "装备：每5秒恢复 4 点法力值。", ["Classes: Paladin"] = "职业：圣骑士", ["Requires Level 55"] = "需要等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Increases the effective spell power of your Holy Shock when used as a healing spell by 10%."] = "(4) 套装：神圣震击作为治疗法术使用时，受到的法术强度加成提高 10%。", ["(6) Set: Your Cleanse spell also heals the target for 200."] = "(6) 套装：你的清洁术还会为目标恢复 200. 点生命值。" }, "Truthful Breastplate"},
