    [61479] = {"镀金头盔", "拾取后绑定\n头部\n469 护甲\n+15 耐力\n+14 力量\n装备：攻击强度提高 21 点。\n装备：近战和远程攻击爆击几率提高 1%。\n装备：受到其他玩家的伤害降低 2%。\n职业：战士\n需要等级 55\n(2) 套装：受到其他玩家的伤害降低 2%。\n(4) 套装：拦截的冷却时间缩短 5 秒。\n(6) 套装：移动速度提高 3% 。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Head"] = "头部", ["469 Armor"] = "469 护甲", ["+15 Stamina"] = "+15 耐力", ["+14 Strength"] = "+14 力量", ["Equip: Increases attack power by 21."] = "装备：攻击强度提高 21 点。", ["Equip: Improves your chance to get a critical strike with melee and ranged attacks by 1%."] = "装备：近战和远程攻击爆击几率提高 1%。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Classes: Warrior"] = "职业：战士", ["Requires Level 55"] = "需要等级 55", ["(2) Set: Decreases your damage taken from other players by 2%."] = "(2) 套装：受到其他玩家的伤害降低 2%。", ["(4) Set: Reduces the cooldown of your Intercept ability by 5 sec."] = "(4) 套装：拦截的冷却时间缩短 5 秒。", ["(6) Set: Increases your movement speed by 3%."] = "(6) 套装：移动速度提高 3% 。" }, "Plated Helm"},
