    [65698] = {"哀叹之靴", "拾取后绑定\n脚\n251 护甲\n+10 敏捷\n+13 耐力\n+13 力量\n装备：攻击强度提高 20 点。\n需要等级 57\n物品等级 62", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Feet"] = "脚", ["251 Armor"] = "251 护甲", ["+10 Agility"] = "+10 敏捷", ["+13 Stamina"] = "+13 耐力", ["+13 Strength"] = "+13 力量", ["Equip: Increases attack power by 20."] = "装备：攻击强度提高 20 点。", ["Requires Level 57"] = "需要等级 57", ["Item Level 62"] = "物品等级 62" }, "Boots of Lamentation"},
