    [70000] = {"黑铁镐", "拾取后绑定\n主手\n+10 力量\n速度 2.80\n唯一\n该物品将触发一个任务\n67 - 126 伤害\n（每秒造成 34.5 点伤害）\n需要等级 55\n物品等级 58", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Main Hand"] = "主手", ["+10 Strength"] = "+10 力量", ["Speed 2.80"] = "速度 2.80", ["Unique"] = "唯一", ["This Item Begins a Quest"] = "该物品将触发一个任务", ["67 - 126 Damage"] = "67 - 126 伤害", ["(34.5 damage per second)"] = "（每秒造成 34.5 点伤害）", ["Requires Level 55"] = "需要等级 55", ["Item Level 58"] = "物品等级 58" }, "Dark Iron Pick"},
    [70001] = {"老化镐升级底座", "拾取后绑定\n使用：升级黑铁镐的底座和说明。上面写着你需要 20 块黑铁锭和 4 块奥金锭，为燃烧精华制作外壳和导流脉络。不需要锻造技能，但需要黑熔炉。\n唯一\n需要等级 55", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Use: Base and instructions for upgrading a Dark Iron Pick, it says you will need 20 Dark Iron Bars and 4 Arcanite Bars to build a housing and channeling vein for a Burning Essence. Smithing not required, however a Black Forge is."] = "使用：升级黑铁镐的底座和说明。上面写着你需要 20 块黑铁锭和 4 块奥金锭，为燃烧精华制作外壳和导流脉络。不需要锻造技能，但需要黑熔炉。", ["Unique"] = "唯一", ["Requires Level 55"] = "需要等级 55" }, "Aged Pick Upgrade Base"},
    [70002] = {"火钢镐", "拾取后绑定\n主手\n+10 力量\n速度 2.73\n唯一\n77 - 145 伤害\n（每秒造成 40.7 点伤害）\n+10 火焰抗性\n需要等级 55\n物品等级 62", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Main Hand"] = "主手", ["+10 Strength"] = "+10 力量", ["Speed 2.73"] = "速度 2.73", ["Unique"] = "唯一", ["77 - 145 Damage"] = "77 - 145 伤害", ["(40.7 damage per second)"] = "（每秒造成 40.7 点伤害）", ["+10 Fire Resistance"] = "+10 火焰抗性", ["Requires Level 55"] = "需要等级 55", ["Item Level 62"] = "物品等级 62" }, "Burningsteel Pickaxe"},
    [90070] = {"元素化身", "使用后绑定\n双手\n+27 敏捷\n+27 力量\n装备：你的攻击被躲闪或招架的几率降低 2%。\n装备：所有法术和攻击的爆击几率提高 2%。\n唯一\n（每秒造成 91.0 点伤害）\n需要等级 60\n物品等级 84", "EpochHead 物品", "item", { ["Binds when used"] = "使用后绑定", ["Two-Hand"] = "双手", ["+27 Agility"] = "+27 敏捷", ["+27 Strength"] = "+27 力量", ["Equip: Reduces your chance to be dodged or parried by 2%."] = "装备：你的攻击被躲闪或招架的几率降低 2%。", ["Equip: Improves your chance to get a critical strike with all spells and attacks by 2%."] = "装备：所有法术和攻击的爆击几率提高 2%。", ["Unique"] = "唯一", ["(91.0 damage per second)"] = "（每秒造成 91.0 点伤害）", ["Requires Level 60"] = "需要等级 60", ["Item Level 84"] = "物品等级 84" }, "Elemental Manifestation"},
    [90071] = {"吉利吉姆地雷", "拾取后绑定\n使用：在地上放置一枚地雷。当敌对生物经过附近时，地雷会爆炸，造成 394 到 506 点火焰伤害并将其击退。地雷持续 2分钟。\n吉利吉姆岛\n唯一\n持续时间：7分钟\n看起来足够稳定……？", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Use: Places a Land Mine on the ground. When a hostile creature passes near, It will explode for 394 to 506 fire damage and knock them away. The mine has a duration of 2 min."] = "使用：在地上放置一枚地雷。当敌对生物经过附近时，地雷会爆炸，造成 394 到 506 点火焰伤害并将其击退。地雷持续 2分钟。", ["Gillijim's Isle"] = "吉利吉姆岛", ["Unique"] = "唯一", ["Duration: 7 min"] = "持续时间：7分钟", ["\"Looks stable enough...?\""] = "看起来足够稳定……？" }, "Gillijim Land Mine"},
