    [90075] = {"蜂蜜黄油面包", "拾取后绑定\n使用：在 30秒 内恢复 2550 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，15 所有抗性，持续 6分钟。\n需要等级 55\n好吃到你根本不想和任何人分享。", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Use: Restores 2550 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 15 All Resistances for 6 minutes."] = "使用：在 30秒 内恢复 2550 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，15 所有抗性，持续 6分钟。", ["Requires Level 55"] = "需要等级 55", ["\"So good you don't even want to share it with anyone.\""] = "好吃到你根本不想和任何人分享。" }, "Honey Butter Bread"},
    [90076] = {"易投“大炸弹”", "拾取后绑定\n使用：造成 132 到 218 点火焰伤害，并击退那个不幸的受害者……不管最后是谁。\n吉利吉姆岛\n唯一\n持续时间：4分钟", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Use: Inflicts 132 to 218 Fire damage and knocks the unfortunate victim away... Whoever that ends up being."] = "使用：造成 132 到 218 点火焰伤害，并击退那个不幸的受害者……不管最后是谁。", ["Gillijim's Isle"] = "吉利吉姆岛", ["Unique"] = "唯一", ["Duration: 4 min"] = "持续时间：4分钟" }, "EZ-Thro \"Da Bomba\""},
