    [90100] = {"龙骨指环", "拾取后绑定\n手指\n+8 耐力\n+14 力量\n装备：近战和远程攻击命中几率提高 1%。\n装备：你的攻击被躲闪或招架的几率降低 1%。\n唯一装备\n需要等级 60\n物品等级 65", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Finger"] = "手指", ["+8 Stamina"] = "+8 耐力", ["+14 Strength"] = "+14 力量", ["Equip: Improves your chance to hit with melee and ranged attacks by 1%."] = "装备：近战和远程攻击命中几率提高 1%。", ["Equip: Reduces your chance to be dodged or parried by 1%."] = "装备：你的攻击被躲闪或招架的几率降低 1%。", ["Unique-Equipped"] = "唯一装备", ["Requires Level 60"] = "需要等级 60", ["Item Level 65"] = "物品等级 65" }, "Dragonbone Ring"},
    [90101] = {"利爪吊坠", "拾取后绑定\n颈部\n+12 耐力\n装备：法术施放速度提高，且周期性法术效果触发频率提高 1%。\n装备：所有魔法法术和效果的治疗效果最多提高 28 点，造成的伤害最多提高 9 点。\n需要等级 60\n物品等级 65", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Neck"] = "颈部", ["+12 Stamina"] = "+12 耐力", ["Equip: Improves your casting speed and causes periodic effects to occur more frequently with spells by 1%."] = "装备：法术施放速度提高，且周期性法术效果触发频率提高 1%。", ["Equip: Increases healing done by up to 28 and damage done by up to 9 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 28 点，造成的伤害最多提高 9 点。", ["Requires Level 60"] = "需要等级 60", ["Item Level 65"] = "物品等级 65" }, "Talon Pendant"},
    [90102] = {"党派", "拾取后绑定\n双手\n+25 敏捷\n+12 耐力\n装备：近战和远程攻击爆击几率提高 2%。\n速度 3.80\n165 - 302 伤害\n（每秒造成 61.4 点伤害）\n+10 火焰抗性\n需要等级 60", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Two-Hand"] = "双手", ["+25 Agility"] = "+25 敏捷", ["+12 Stamina"] = "+12 耐力", ["Equip: Improves your chance to get a critical strike with melee and ranged attacks by 2%."] = "装备：近战和远程攻击爆击几率提高 2%。", ["Speed 3.80"] = "速度 3.80", ["165 - 302 Damage"] = "165 - 302 伤害", ["(61.4 damage per second)"] = "（每秒造成 61.4 点伤害）", ["+10 Fire Resistance"] = "+10 火焰抗性", ["Requires Level 60"] = "需要等级 60" }, "Partisane"},
