    [90549] = {"无尽指环", "拾取后绑定\n手指\n+5 智力\n+8 精神\n装备：法术施放速度提高，且周期性法术效果触发频率提高 1%。\n装备：所有魔法法术和效果的治疗效果最多提高 25 点，造成的伤害最多提高 8 点。\n唯一装备\n需要等级 60\n物品等级 65", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Finger"] = "手指", ["+5 Intellect"] = "+5 智力", ["+8 Spirit"] = "+8 精神", ["Equip: Improves your casting speed and causes periodic effects to occur more frequently with spells by 1%."] = "装备：法术施放速度提高，且周期性法术效果触发频率提高 1%。", ["Equip: Increases healing done by up to 25 and damage done by up to 8 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 25 点，造成的伤害最多提高 8 点。", ["Unique-Equipped"] = "唯一装备", ["Requires Level 60"] = "需要等级 60", ["Item Level 65"] = "物品等级 65" }, "Band of the Endless"},
    [90550] = {"竞争者的冥想斗篷", "拾取后绑定\n背部\n40 护甲\n+10 精神\n+13 耐力\n装备：所有魔法法术和效果的治疗效果最多提高 18 点，造成的伤害最多提高 6 点。\n装备：受到其他玩家的伤害降低 1%。\n需要等级 60\n物品等级 60", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Back"] = "背部", ["40 Armor"] = "40 护甲", ["+10 Spirit"] = "+10 精神", ["+13 Stamina"] = "+13 耐力", ["Equip: Increases healing done by up to 18 and damage done by up to 6 for all magical spells and effects."] = "装备：所有魔法法术和效果的治疗效果最多提高 18 点，造成的伤害最多提高 6 点。", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["Requires Level 60"] = "需要等级 60", ["Item Level 60"] = "物品等级 60" }, "Contender's Cloak of Meditation"},
