    [90687] = {"对手的法术护盾", "拾取后绑定\n副手\n2314 护甲\n+8 智力\n+9 耐力\n装备：法术爆击几率提高 1%。\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 10 点。\n装备：对其他玩家造成的伤害提高 3%。\n装备：受到其他玩家的伤害降低 1%。\n45 格挡。\n职业：战士、圣骑士、萨满祭司\n需要等级 60\n物品等级 65", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Off Hand"] = "副手", ["2314 Armor"] = "2314 护甲", ["+8 Intellect"] = "+8 智力", ["+9 Stamina"] = "+9 耐力", ["Equip: Improves your chance to get a critical strike with spells by 1%."] = "装备：法术爆击几率提高 1%。", ["Equip: Increases damage and healing done by magical spells and effects by up to 10."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 10 点。", ["Equip: Increases your damage dealt against other players by 3%."] = "装备：对其他玩家造成的伤害提高 3%。", ["Equip: Decreases your damage taken from other players by 1%."] = "装备：受到其他玩家的伤害降低 1%。", ["45 Block"] = "45 格挡。", ["Classes: Warrior, Paladin, Shaman"] = "职业：战士、圣骑士、萨满祭司", ["Requires Level 60"] = "需要等级 60", ["Item Level 65"] = "物品等级 65" }, "Rival's Spellshield"},
