    [90689] = {"对手的霜指", "拾取后绑定\n远程\n+6 智力\n+11 耐力\n装备：魔法法术和效果造成的伤害与治疗效果最多提高 8 点。\n装备：受到其他玩家的伤害降低 2%。\n速度 1.60\n85 - 160 伤害\n（每秒造成 76.6 点伤害）\n职业：牧师、法师、术士\n需要等级 60", "EpochHead 物品", "item", { ["Binds when picked up"] = "拾取后绑定", ["Ranged"] = "远程", ["+6 Intellect"] = "+6 智力", ["+11 Stamina"] = "+11 耐力", ["Equip: Increases damage and healing done by magical spells and effects by up to 8."] = "装备：魔法法术和效果造成的伤害与治疗效果最多提高 8 点。", ["Equip: Decreases your damage taken from other players by 2%."] = "装备：受到其他玩家的伤害降低 2%。", ["Speed 1.60"] = "速度 1.60", ["85 - 160 Damage"] = "85 - 160 伤害", ["(76.6 damage per second)"] = "（每秒造成 76.6 点伤害）", ["Classes: Priest, Mage, Warlock"] = "职业：牧师、法师、术士", ["Requires Level 60"] = "需要等级 60" }, "Rival's Frostfinger"},
